import ast
import calendar
import csv
import json
from collections import defaultdict
from datetime import date, timedelta


EMPLOYEES_PATH = "/app/dataset/employees.csv"
TASKS_PATH = "/app/dataset/tasks.csv"
TIMESHEET_PATH = "/app/dataset/timesheet.csv"
ANSWER_JSON_PATH = "/app/answer.json"


def _load_csv(path: str) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def _correct_date(raw_date: str) -> date:
    year, month, day = map(int, raw_date.split("-"))
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last_day))


def _parse_tasks(raw_tasks: str) -> list[int]:
    try:
        value = ast.literal_eval(raw_tasks)
        if isinstance(value, (list, tuple)):
            return [int(item) for item in value]
    except Exception:
        pass

    tokens = [
        token.strip()
        for token in raw_tasks.replace("[", "").replace("]", "").split(",")
        if token.strip()
    ]
    if tokens and all(token.isdigit() for token in tokens):
        return [int(token) for token in tokens]
    return []


def _hamming_distance(left: int, right: int) -> int:
    left_str = str(left)
    right_str = str(right)
    if len(left_str) != len(right_str):
        return 10**9
    return sum(a != b for a, b in zip(left_str, right_str))


def _closest_pesel(bad_pesel: str, valid_pesels: list[str]) -> str:
    return min(
        valid_pesels,
        key=lambda pesel: (
            sum(a != b for a, b in zip(bad_pesel, pesel))
            + abs(len(bad_pesel) - len(pesel)),
            abs(int(bad_pesel) - int(pesel)),
            pesel,
        ),
    )


def _closest_task(task_id: int, valid_task_ids: list[int]) -> int:
    return min(
        valid_task_ids,
        key=lambda valid_task_id: (
            _hamming_distance(task_id, valid_task_id),
            abs(task_id - valid_task_id),
            valid_task_id,
        ),
    )


def _month_floor(value: date) -> date:
    return date(value.year, value.month, 1)


def _next_month(value: date) -> date:
    if value.month == 12:
        return date(value.year + 1, 1, 1)
    return date(value.year, value.month + 1, 1)


def _billing_period_starts(dates: list[date]) -> list[date]:
    first_date = min(dates)
    last_date = max(dates)
    weekday = first_date.weekday()

    starts: list[date] = []
    current = _month_floor(first_date)
    end = _month_floor(last_date)
    while current <= end:
        start = current
        while start.weekday() != weekday:
            start += timedelta(days=1)
        starts.append(start)
        current = _next_month(current)
    return starts


def _period_start(value: date, starts: list[date]) -> date:
    for start in reversed(starts):
        if value >= start:
            return start
    return starts[0]


def answer() -> dict[str, list[int]]:
    employees = _load_csv(EMPLOYEES_PATH)
    tasks = _load_csv(TASKS_PATH)
    timesheet = _load_csv(TIMESHEET_PATH)

    valid_pesels = sorted(employee["PESEL"] for employee in employees)
    hourly_rates = {
        employee["PESEL"]: int(float(employee["hourly_rate"])) for employee in employees
    }
    task_pay = {
        int(task["task_id"]): int(float(task["pay_per_completion"])) for task in tasks
    }
    valid_task_ids = sorted(task_pay)

    valid_employee_keys = {
        (
            row["employee_id"],
            row["date"],
            row["facility_id"],
            row["hours_worked"],
        )
        for row in timesheet
        if row["employee_id"] in hourly_rates
    }

    cleaned_rows: list[dict[str, object]] = []
    for row in timesheet:
        employee_id = row["employee_id"]
        if employee_id not in hourly_rates:
            mapped_pesel = _closest_pesel(employee_id, valid_pesels)
            duplicate_key = (
                mapped_pesel,
                row["date"],
                row["facility_id"],
                row["hours_worked"],
            )
            if duplicate_key in valid_employee_keys:
                continue
            employee_id = mapped_pesel

        cleaned_rows.append(
            {
                "id": row["id"],
                "employee_id": employee_id,
                "date": _correct_date(row["date"]),
                "facility_id": row["facility_id"],
                "salary_amount": int(float(row["salary_amount"])),
                "tasks": [
                    task_id if task_id in task_pay else _closest_task(task_id, valid_task_ids)
                    for task_id in _parse_tasks(row["performed_tasks"])
                ],
            }
        )

    unique_rows: list[dict[str, object]] = []
    seen_rows: set[tuple[tuple[str, object], ...]] = set()
    for row in cleaned_rows:
        key = tuple(sorted((field, value) for field, value in row.items() if field != "id"))
        if key in seen_rows:
            continue
        seen_rows.add(key)
        unique_rows.append(row)

    billing_starts = _billing_period_starts([row["date"] for row in unique_rows])

    rows_by_employee_period: defaultdict[tuple[str, date], list[dict[str, object]]] = defaultdict(list)
    for row in unique_rows:
        row["period_start"] = _period_start(row["date"], billing_starts)
        rows_by_employee_period[(row["employee_id"], row["period_start"])].append(row)

    totals: dict[str, dict[date, int]] = {
        pesel: {period_start: 0 for period_start in billing_starts}
        for pesel in valid_pesels
    }

    for (employee_id, period_start), rows in rows_by_employee_period.items():
        rows.sort(key=lambda row: (row["salary_amount"], row["date"], int(row["id"])))
        previous_salary: int | None = None
        hourly_rate = hourly_rates[employee_id]

        for row in rows:
            current_salary = row["salary_amount"]
            salary_delta = current_salary if previous_salary is None else current_salary - previous_salary
            previous_salary = current_salary

            if salary_delta <= 0:
                continue
            if salary_delta % hourly_rate != 0:
                continue

            derived_hours = salary_delta // hourly_rate
            if not 1 <= derived_hours <= 8:
                continue

            bonus = sum(task_pay[task_id] for task_id in row["tasks"])
            totals[employee_id][period_start] += salary_delta + bonus

    return {
        pesel: [int(totals[pesel][period_start]) for period_start in billing_starts]
        for pesel in valid_pesels
    }


if __name__ == "__main__":
    with open(ANSWER_JSON_PATH, "w", encoding="utf-8") as handle:
        json.dump(answer(), handle, ensure_ascii=False)
